/**
 * What the home's and a conversation's composers share: the images it takes (admin-api's limits, the
 * smaller total on Cloudflare), whether the assistant can search the web, the attachments a message
 * sends, and how an assistant is named (`assistantName`). The "/" menu lists only the commands the App
 * registered (`agent.command`, `GET /admin/api/commands`, read by the shell): the dashboard's own
 * actions (stop, reset, images, web search, the assistant, the views) are its buttons, never commands.
 */

import type { ComposerImage, ImageLimits, PickerOption } from "@/components/bui/PromptBar";
import { IMAGE_TYPES, MAX_DURABLE_IMAGE_BYTES, MAX_IMAGE_BYTES, MAX_IMAGES, WEB_SEARCH_TOOL } from "@/lib/admin-api";
import type { ApiAgent, ApiApp, ApiAttachment } from "@/lib/api";
import { assistantName } from "@/lib/names";

export { assistantName };

export const imageLimits = (app: ApiApp): ImageLimits => ({
  types: IMAGE_TYPES,
  count: MAX_IMAGES,
  bytes: MAX_IMAGE_BYTES,
  ...(app.target === "durable" && { totalBytes: MAX_DURABLE_IMAGE_BYTES }),
});

/** Whether `agent` searches the web (it has `WEB_SEARCH_TOOL`), and why not. */
export function webSearchOf(agents: ApiAgent[] | undefined, agent: string | undefined): { available: boolean; unavailable: string } {
  const found = agents?.find((each) => each.name === agent);
  return {
    available: found?.tools.includes(WEB_SEARCH_TOOL) === true,
    unavailable: agents === undefined ? "The assistants are not read yet" : `${agent === undefined ? "This assistant" : assistantName(agent)} has no web search tool`,
  };
}

export const attachmentsOf = (images: ComposerImage[]): ApiAttachment[] => images.map(({ mimeType, data }) => ({ kind: "image", mimeType, data }));

/** The assistants as the composer's picker lists them: by their shown name, `tag`s for some. */
export const assistantOptions = (names: string[], tag: (name: string) => string | undefined = () => undefined): PickerOption[] =>
  names.map((name) => {
    const tagged = tag(name);
    return { key: name, name: assistantName(name), ...(tagged !== undefined && { tag: tagged }) };
  });

/**
 * The Context panel (Beautiful UI's right-hand pane, as its harness shows retrieved chunks): what this
 * conversation's transcript holds besides its words, as far as it is read here: the images sent in it
 * and its sources (`sources.ts`), or an empty state.
 */

import { MediaImage, Xmark } from "iconoir-react";
import ContextCards, { ContextHeader } from "@/components/bui/ContextCards";
import EmptyState from "@/components/bui/EmptyState";
import type { SentImage, Source } from "./sources";

export function ContextPanel({ images, sources, onClose }: { images: SentImage[]; sources: Source[]; onClose: () => void }) {
  return (
    <aside aria-label="Context" className="hidden w-[360px] shrink-0 flex-col overflow-hidden rounded-window border border-line bg-page lg:flex" style={{ animation: "fade-in 300ms ease both" }}>
      <div className="flex h-11 shrink-0 items-center justify-between border-b border-line px-3 sm:pl-4">
        <span className="text-[13px] font-semibold text-ink">Context</span>
        <button type="button" aria-label="Close the context" onClick={onClose} className="flex size-6 items-center justify-center rounded-[6px] text-ink-3 transition-colors duration-100 hover:bg-hover hover:text-ink">
          <Xmark width={15} height={15} strokeWidth={2} />
        </button>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto p-4">
        {images.length === 0 && sources.length === 0 ? (
          <EmptyState icon={<MediaImage />} title="Nothing here yet" hint="The images sent in this conversation, and what its web searches and fetches found, show here." />
        ) : (
          <div className="flex flex-col gap-6">
            {images.length > 0 && (
              <section className="flex flex-col gap-2">
                <ContextHeader title="Attachments" count={images.length} />
                <div className="grid grid-cols-3 gap-2">
                  {images.map((image, i) => (
                    <img
                      key={image.key}
                      src={`data:${image.mimeType};base64,${image.data}`}
                      alt={`Image ${i + 1}`}
                      title={image.at === undefined ? image.mimeType : `${image.mimeType}, sent ${new Date(image.at).toLocaleString()}`}
                      className="aspect-square w-full rounded-card bg-inset object-cover shadow-card"
                      style={{ animation: `fade-up 400ms cubic-bezier(0.23,1,0.32,1) ${Math.min(i, 8) * 60}ms both` }}
                    />
                  ))}
                </div>
              </section>
            )}
            {sources.length > 0 && <ContextCards header="Sources" chunks={sources} />}
          </div>
        )}
      </div>
    </aside>
  );
}

/**
 * One conversation, live: its transcript, the answer being written, the thinking and the tools
 * running; and what an operator does to it (SPEC §5): a message (with images, a web search), a stop,
 * a reset. Its top bar holds nothing but two buttons: the Context panel (the images sent in it, what
 * its web searches and fetches found) and a menu with the reset. Its composer shows its assistant: a
 * conversation never changes agent, so picking another starts a new chat with it. Its "/" runs the
 * App's commands here (`POST …/commands/:name`): what one answers is a quiet note in the thread, for
 * the operator only (no channel gets it); one that left the conversation behind (`/new`) is followed
 * to its key's new conversation, the note with it.
 *
 * The dashboard is a channel of its own: a message from here is a follow-up (it waits for a run
 * going) whose answer stays here. In another channel's conversation nothing said here reaches that
 * channel's chat (the agent reads that the message is the operator's, and that the user sees neither
 * it nor the answer); a run that also answers a user's message is delivered to the user, as always.
 */

import { MoreHoriz, Refresh, SidebarExpand } from "iconoir-react";
import { type RefObject, useEffect, useLayoutEffect, useRef, useState } from "react";
import GlideMenu from "@/components/bui/GlideMenu";
import { LoaderGrid } from "@/components/bui/LoadingState";
import PromptBar, { type ComposerMessage } from "@/components/bui/PromptBar";
import { ErrorNote } from "@/components/pikit/error-note";
import { type Message, Reply, turnsOf, UserBubble, userText } from "@/components/pikit/message";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { isDashboardKey } from "@/lib/admin-api";
import {
  api,
  type ApiCommandResponse,
  type ApiConversation,
  type ApiPage,
  type ApiResetResponse,
  type ApiSendResponse,
  type ApiTranscriptEntry,
  post,
  useApi,
} from "@/lib/api";
import { agentsOf, type CommandNote, useChats } from "@/lib/chats";
import { navigate, pagePath } from "@/lib/router";
import { SidePanel, TabActions, useShell } from "@/lib/shell";
import { assistantOptions, attachmentsOf, imageLimits, webSearchOf } from "./composer";
import { ContextPanel } from "./context";
import { useLive } from "./live";
import { imagesOf, sourcesOf } from "./sources";

const PAGE = 50;
const CONTEXT = "pikit-context";

/** The transcript's latest page, read again when the conversation changes, and older pages on demand. */
function useTranscript(id: string, changes: number) {
  const latest = useApi<ApiPage<ApiTranscriptEntry>>(`/conversations/${encodeURIComponent(id)}/transcript?limit=${PAGE}`);
  const [older, setOlder] = useState<ApiTranscriptEntry[]>([]);
  const [cursor, setCursor] = useState<string | null>();
  const { reload } = latest;

  useEffect(() => {
    if (changes === 0) return;
    const timer = setTimeout(reload, 250);
    return () => clearTimeout(timer);
  }, [changes, reload]);

  const next = cursor === undefined ? latest.data?.next : (cursor ?? undefined);
  const loadOlder = async () => {
    if (next === undefined) return;
    const page = await api<ApiPage<ApiTranscriptEntry>>(`/conversations/${encodeURIComponent(id)}/transcript?limit=${PAGE}&cursor=${encodeURIComponent(next)}`);
    setOlder((items) => [...items, ...page.items]);
    setCursor(page.next ?? null);
  };

  // Newest first from the API; shown oldest first.
  const seen = new Set<string>();
  const entries = [...(latest.data?.items ?? []), ...older].filter((entry) => !seen.has(entry.id) && seen.add(entry.id)).reverse();
  return { entries, loaded: latest.data !== undefined, error: latest.error, hasOlder: next !== undefined, loadOlder };
}

/** Whether the Context panel shows (remembered in this browser; closed at first). */
function useContextOpen(): [boolean, (open: boolean) => void] {
  const [open, setOpen] = useState(() => {
    try {
      return localStorage.getItem(CONTEXT) === "open";
    } catch {
      return false;
    }
  });
  const set = (next: boolean) => {
    setOpen(next);
    try {
      localStorage.setItem(CONTEXT, next ? "open" : "closed");
    } catch {
      // Not remembered.
    }
  };
  return [open, set];
}

/** The conversation's menu: its reset, which `onReset` confirms first. */
function ConversationMenu({ actionable, onReset }: { actionable: boolean; onReset: () => void }) {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-conversation-menu]")) setOpen(false);
    };
    const escape = (event: KeyboardEvent) => event.key === "Escape" && setOpen(false);
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [open]);

  return (
    <div data-conversation-menu className="relative">
      <button
        type="button"
        aria-label="Conversation actions"
        aria-expanded={open}
        disabled={!actionable}
        onClick={() => setOpen((current) => !current)}
        className="flex size-7 items-center justify-center rounded-[7px] text-ink-3 transition-colors duration-100 enabled:hover:bg-hover enabled:hover:text-ink disabled:opacity-40"
      >
        <MoreHoriz width={16} height={16} strokeWidth={2} />
      </button>
      {open && (
        <div className="absolute top-full right-0 z-50 mt-1.5 w-56 rounded-[14px] bg-surface p-1.5 shadow-overlay" style={{ animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: "top right" }}>
          <GlideMenu className="flex flex-col gap-px" highlightClassName="inset-x-0 rounded-[8px] bg-hover-2">
            <button
              data-menu-row
              type="button"
              onClick={() => {
                setOpen(false);
                onReset();
              }}
              className="relative z-10 flex h-9 w-full items-center gap-2 rounded-[8px] px-2 text-left text-[13.5px] text-red"
            >
              <Refresh width={16} height={16} strokeWidth={1.9} />
              Reset conversation…
            </button>
          </GlideMenu>
        </div>
      )}
    </div>
  );
}

/** The reset, confirmed: the key starts again in a new conversation, which the page follows. */
function ResetDialog({ conversation, open, onOpenChange, onError }: { conversation: ApiConversation; open: boolean; onOpenChange: (open: boolean) => void; onError: (error: Error | undefined) => void }) {
  const chats = useChats();
  const reset = async () => {
    onError(undefined);
    try {
      const done = await post<ApiResetResponse>(`/conversations/${encodeURIComponent(conversation.conversationId)}/reset`);
      chats.replaced(conversation.conversationId, done.conversationId);
      chats.reload();
      navigate(pagePath("/conversations", done.conversationId), { replace: true });
    } catch (thrown) {
      onError(thrown instanceof Error ? thrown : new Error(String(thrown)));
    }
  };
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Reset this conversation?</AlertDialogTitle>
          <AlertDialogDescription>
            {isDashboardKey(conversation.key) ? "This chat" : conversation.key} starts again with an empty history. This conversation is kept and stays readable here; a run still going finishes in it.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction className="bg-red text-white hover:bg-red/90" onClick={() => void reset()}>
            Reset
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/** What a command answered: a quiet note in the thread, the operator's only. */
function CommandNoteRow({ note }: { note: CommandNote }) {
  return (
    <div className="flex items-start gap-2.5 rounded-card bg-inset px-3 py-2.5 shadow-hairline" style={{ animation: "fade-up 320ms cubic-bezier(0.23,1,0.32,1) both" }}>
      <span className="mt-px flex h-5 shrink-0 items-center rounded-chip bg-surface px-1.5 font-mono text-[11.5px] text-ink-2 shadow-hairline">/{note.command}</span>
      <p className="min-w-0 flex-1 text-[13px] leading-5 text-ink-2 [overflow-wrap:anywhere]">{note.text}</p>
      <span className="mt-0.5 shrink-0 text-[11px] text-ink-3">Only you see this</span>
    </div>
  );
}

/** The thread follows its end while the operator is there; scrolling up to read releases it. */
function useStickToBottom(scroller: RefObject<HTMLDivElement | null>, id: string) {
  useEffect(() => {
    const el = scroller.current;
    const content = el?.firstElementChild;
    if (!el || !content) return;
    let stick = true;
    let raf = 0;
    const onScroll = () => {
      stick = el.scrollHeight - el.scrollTop - el.clientHeight < 120;
    };
    const pin = () => {
      if (!stick) return;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        el.scrollTop = el.scrollHeight;
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    const resize = new ResizeObserver(pin);
    resize.observe(content);
    const mutate = new MutationObserver(pin);
    mutate.observe(content, { childList: true, subtree: true, characterData: true });
    pin();
    return () => {
      el.removeEventListener("scroll", onScroll);
      resize.disconnect();
      mutate.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [scroller, id]);
}

export function ConversationPage({ params }: { params: Record<string, string> }) {
  const id = params.id ?? "";
  const chats = useChats();
  const { app, agents: described, commands, newChat } = useShell();
  const agents = agentsOf(app);
  const live = useLive(id);
  const summary = useApi<ApiConversation>(`/conversations/${encodeURIComponent(id)}`);
  const transcript = useTranscript(id, live.changes);
  const [contextOpen, setContextOpen] = useContextOpen();
  const [confirming, setConfirming] = useState(false);
  const [actionError, setActionError] = useState<Error>();
  const [note, setNote] = useState<string>();
  const scrollRef = useRef<HTMLDivElement>(null);
  const composerRef = useRef<HTMLDivElement>(null);
  const [composerH, setComposerH] = useState(150);
  const { reload } = summary;
  const conversation = summary.data?.conversationId === id ? summary.data : undefined;

  useEffect(() => {
    if (live.changes === 0) return;
    const timer = setTimeout(reload, 250);
    return () => clearTimeout(timer);
  }, [live.changes, live.busy, reload]);

  const { openTab, setFirstMessage } = chats;
  useEffect(() => {
    if (conversation !== undefined) openTab(conversation);
  }, [conversation, openTab]);

  const messages = transcript.entries.flatMap((entry) => entry.messages as Message[]);
  const turns = turnsOf(messages, live);

  // Until the API titles its key, a chat is named by the first words written in it, once read here.
  const firstText = transcript.hasOlder ? undefined : turns.map((turn) => (turn.kind === "user" ? userText(turn.message).text.trim() : "")).find((text) => text !== "");
  useEffect(() => {
    if (conversation?.key !== undefined && conversation.title === undefined && firstText !== undefined) setFirstMessage(conversation.key, firstText);
  }, [conversation, firstText, setFirstMessage]);
  const notes = chats.notesOf(id);

  useStickToBottom(scrollRef, id);

  useLayoutEffect(() => {
    const el = composerRef.current;
    if (!el) return;
    const measure = () => setComposerH(el.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [conversation?.current]);

  useEffect(() => {
    if (note === undefined) return;
    const timer = setTimeout(() => setNote(undefined), 6000);
    return () => clearTimeout(timer);
  }, [note]);

  if (summary.error !== undefined) {
    return (
      <div className="mx-auto w-full max-w-[720px] p-8">
        <ErrorNote error={summary.error} title="This conversation cannot be read" />
      </div>
    );
  }

  // Waiting for the model: the run goes and nothing is being written or run.
  const streaming = live.partial !== undefined || live.tools.length > 0;
  const waiting = live.busy && !streaming;
  const last = turns.at(-1);
  const since = [...messages].reverse().find((message) => message.timestamp !== undefined)?.timestamp;
  const dashboardOwn = isDashboardKey(conversation?.key);
  const actionable = conversation?.current === true;
  const webSearch = webSearchOf(described, conversation?.agent);
  const send = async ({ text, images, webSearch: search }: ComposerMessage) => {
    if (conversation === undefined) return;
    try {
      const sent = await post<ApiSendResponse>(`/conversations/${encodeURIComponent(conversation.conversationId)}/messages`, {
        text,
        ...(images.length > 0 && { attachments: attachmentsOf(images) }),
        ...(search && { webSearch: true }),
      });
      setActionError(undefined);
      setNote(sent.admission === "queued" ? "Sent: it runs once the run going ends." : sent.admission === "duplicate" ? "Already sent." : undefined);
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown : new Error(String(thrown)));
      throw thrown;
    }
  };
  /**
   * Runs `/name args` here. Its note stays in this page; a command that left this conversation behind
   * (`/new`) is followed to its key's current one, which gets the note.
   */
  const runCommand = async (name: string, args: string) => {
    if (conversation === undefined) return;
    try {
      const answer = await post<ApiCommandResponse>(`/conversations/${encodeURIComponent(conversation.conversationId)}/commands/${encodeURIComponent(name)}`, { args });
      setActionError(undefined);
      let target = conversation.conversationId;
      const now = await api<ApiConversation>(`/conversations/${encodeURIComponent(conversation.conversationId)}`).catch(() => undefined);
      if (now?.current === false && now.key !== undefined) {
        const page = await api<ApiPage<ApiConversation>>("/conversations?limit=50").catch(() => undefined);
        target = page?.items.find((each) => each.key === now.key && each.current === true)?.conversationId ?? target;
      }
      chats.addNote(target, name, answer.text ?? `Ran /${name}.`);
      chats.reload();
      if (target === conversation.conversationId) reload();
      else {
        chats.replaced(conversation.conversationId, target);
        navigate(pagePath("/conversations", target), { replace: true });
      }
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown : new Error(String(thrown)));
      throw thrown;
    }
  };
  const stop = () => {
    if (conversation === undefined) return;
    post(`/conversations/${encodeURIComponent(conversation.conversationId)}/abort`).then(
      () => setActionError(undefined),
      (thrown: unknown) => setActionError(thrown instanceof Error ? thrown : new Error(String(thrown))),
    );
  };

  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
      {conversation !== undefined && (
        <TabActions>
          <button
            type="button"
            aria-label="Context"
            aria-pressed={contextOpen}
            title="Context: the images sent here, and what its web searches and fetches found"
            onClick={() => setContextOpen(!contextOpen)}
            className={`hidden size-7 items-center justify-center rounded-[7px] transition-colors duration-100 lg:flex ${contextOpen ? "bg-hover-2 text-ink" : "text-ink-3 hover:bg-hover hover:text-ink"}`}
          >
            <SidebarExpand width={16} height={16} strokeWidth={1.9} />
          </button>
          <ConversationMenu actionable={actionable} onReset={() => setConfirming(true)} />
        </TabActions>
      )}
      {conversation !== undefined && <ResetDialog conversation={conversation} open={confirming} onOpenChange={setConfirming} onError={setActionError} />}

      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto overscroll-contain">
        <div className="flex flex-col gap-8 px-4 pt-8 sm:px-8 lg:px-12" style={{ paddingBottom: composerH + 16 }}>
          {transcript.hasOlder && (
            <div className="mx-auto w-full max-w-[720px]">
              <button type="button" onClick={() => void transcript.loadOlder()} className="mx-auto flex h-7 items-center rounded-full px-3 text-[12.5px] font-medium text-ink-2 shadow-btn transition-colors duration-100 hover:bg-hover">
                Earlier messages
              </button>
            </div>
          )}
          {transcript.error !== undefined && (
            <div className="mx-auto w-full max-w-[720px]">
              <ErrorNote error={transcript.error} />
            </div>
          )}
          {!transcript.loaded && transcript.error === undefined && (
            <div className="mx-auto flex w-full max-w-[720px] items-center gap-2.5 text-[13px] text-ink-3">
              <LoaderGrid /> Loading the conversation
            </div>
          )}
          {turns.map((turn, i) => (
            <div key={turn.key} className="mx-auto flex w-full max-w-[720px] flex-col gap-8">
              {/* a command's note goes before the first message written after it */}
              {turn.kind === "user" &&
                notes
                  .filter((note) => note.at <= (turn.message.timestamp ?? 0) && !turns.slice(0, i).some((before) => before.kind === "user" && note.at <= (before.message.timestamp ?? 0)))
                  .map((note) => <CommandNoteRow key={`note-${note.id}`} note={note} />)}
              {turn.kind === "user" ? (
                <UserBubble message={turn.message} from={conversation?.key} />
              ) : (
                <Reply segments={turn.segments} waiting={waiting && i === turns.length - 1} since={since} />
              )}
            </div>
          ))}
          {notes
            .filter((note) => !turns.some((turn) => turn.kind === "user" && note.at <= (turn.message.timestamp ?? 0)))
            .map((note) => (
              <div key={`note-${note.id}`} className="mx-auto w-full max-w-[720px]">
                <CommandNoteRow note={note} />
              </div>
            ))}
          {waiting && last?.kind !== "reply" && (
            <div className="mx-auto w-full max-w-[720px]">
              <Reply segments={[]} waiting since={since} />
            </div>
          )}
          {transcript.loaded && turns.length === 0 && notes.length === 0 && !live.busy && <p className="mx-auto w-full max-w-[720px] text-[13.5px] text-ink-3">No messages yet.</p>}
        </div>
      </div>

      {/* soft fade so content dissolves into the bar instead of hard-clipping */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0" style={{ height: composerH + 32, background: "linear-gradient(to top, var(--page) 64%, transparent)" }} />

      {/* the composer floats over the thread; content scrolls behind it */}
      <div ref={composerRef} className="absolute inset-x-0 bottom-0 px-4 pb-6 sm:px-8 lg:px-12">
        <div className="mx-auto flex max-w-[720px] flex-col gap-2">
          {actionError !== undefined && <ErrorNote error={actionError} title="That did not work" />}
          {conversation !== undefined && conversation.current !== true ? (
            <p className="rounded-card bg-inset px-3 py-2.5 text-[13px] text-ink-2 shadow-hairline">
              {conversation.current === false ? "A reset left this conversation behind: it can be read, not talked to." : "No message has reached this conversation yet."}
            </p>
          ) : (
            <>
              <PromptBar
                placeholder={live.busy ? "Reply: it runs after the run going" : "Reply"}
                disabled={conversation === undefined}
                picker={
                  conversation?.agent === undefined
                    ? undefined
                    : {
                        label: "assistant",
                        options: assistantOptions(agents.includes(conversation.agent) ? agents : [conversation.agent, ...agents], (name) =>
                          name !== conversation.agent ? "new chat" : undefined,
                        ),
                        value: conversation.agent,
                        onChange: (agent) => newChat(agent),
                        ...(agents.some((name) => name !== conversation.agent) && { note: "A chat keeps its assistant: another one starts a new chat with it." }),
                      }
                }
                images={imageLimits(app)}
                webSearch={webSearch}
                commands={commands ?? []}
                onCommand={runCommand}
                busy={live.busy}
                onStop={stop}
                onSend={send}
              />
              {(note !== undefined || (conversation !== undefined && !dashboardOwn)) && (
                <p className="px-1 text-center text-[12px] text-ink-3">
                  {note ?? `Only you see what you write here, and its answer: nothing reaches ${conversation?.key}'s chat.`}
                </p>
              )}
            </>
          )}
        </div>
      </div>

      {contextOpen && conversation !== undefined && (
        <SidePanel>
          <ContextPanel images={imagesOf(messages)} sources={sourcesOf(messages)} onClose={() => setContextOpen(false)} />
        </SidePanel>
      )}
    </div>
  );
}

/**
 * The home: a new conversation of the dashboard's own. The operator picks one of the App's agents (in
 * the composer, where Beautiful UI picks a model; `?agent=<name>` chooses one, as a conversation's
 * composer does when another is picked there) and writes the first message, with images and a web
 * search when wanted: `POST /admin/api/conversations` makes `dashboard:<uuid>`, whose answers appear
 * only here, and no other channel can continue it. Below, the last conversations, to continue. The
 * "/" menu lists the App's commands, which run in a conversation: here, they say so.
 */

import { ChatBubble } from "iconoir-react";
import { type CSSProperties, useEffect, useState } from "react";
import PromptBar, { type ComposerMessage } from "@/components/bui/PromptBar";
import { ErrorNote } from "@/components/pikit/error-note";
import { type ApiStartResponse, post } from "@/lib/api";
import { agentsOf, defaultAgentOf, NEW_CHAT, useChats } from "@/lib/chats";
import { Link, navigate, pagePath } from "@/lib/router";
import { useShell } from "@/lib/shell";
import { assistantName, assistantOptions, attachmentsOf, imageLimits, webSearchOf } from "./composer";

/* -- the entrance (ms after mount): hello, question, composer, suggestions -- */
const HOME_REVEAL_TIMING = [170, 330, 400, 550];
const HOME_REVEAL = { offsetY: 23, blur: 17, duration: 800, easing: "cubic-bezier(0.16, 1, 0.3, 1)" };
/** The conversations suggested: the most recently active. */
const SUGGESTED = 3;

function homeRevealStyle(visible: boolean): CSSProperties {
  return {
    opacity: visible ? 1 : 0,
    transform: visible ? "translate3d(0, 0, 0)" : `translate3d(0, ${HOME_REVEAL.offsetY}px, 0)`,
    filter: visible ? "blur(0px)" : `blur(${HOME_REVEAL.blur}px)`,
    transition: ["opacity", "transform", "filter"].map((property) => `${property} ${HOME_REVEAL.duration}ms ${HOME_REVEAL.easing}`).join(", "),
  };
}

export function HomePage() {
  const { app, agents: described, commands, operator } = useShell();
  const chats = useChats();
  const agents = agentsOf(app);
  const [agent, setAgent] = useState<string | undefined>(() => new URLSearchParams(window.location.search).get("agent") ?? undefined);
  const [error, setError] = useState<Error>();
  const [stage, setStage] = useState(0);
  const chosen = agent !== undefined && agents.includes(agent) ? agent : defaultAgentOf(app);
  const fallback = defaultAgentOf(app);
  const webSearch = webSearchOf(described, chosen);

  useEffect(() => {
    const timers = HOME_REVEAL_TIMING.map((at, i) => setTimeout(() => setStage(i + 1), at));
    return () => timers.forEach(clearTimeout);
  }, []);

  const start = async ({ text, images, webSearch: search }: ComposerMessage) => {
    if (chosen === undefined) return;
    setError(undefined);
    try {
      const started = await post<ApiStartResponse>("/conversations", { agent: chosen, text, ...(images.length > 0 && { attachments: attachmentsOf(images) }), ...(search && { webSearch: true }) });
      if (text !== "") chats.setFirstMessage(started.key, text);
      chats.reload();
      navigate(pagePath("/conversations", started.conversationId));
    } catch (thrown) {
      setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
      throw thrown;
    }
  };

  // The last conversations, to continue: one per key (a reset's previous ones are not suggested).
  const recent = (chats.items ?? []).filter((conversation) => conversation.key !== undefined && conversation.current !== false).slice(0, SUGGESTED);

  return (
    <div className="min-h-0 flex-1 overflow-y-auto">
      <div className="mx-auto flex min-h-full max-w-[720px] flex-col justify-center px-4 py-10 sm:px-8">
        <h1 className="text-[26px] font-normal tracking-[-0.02em] text-ink">
          <span className="home-reveal block text-ink-3" style={homeRevealStyle(stage >= 1)}>
            Hello{operator === undefined || operator === "operator" ? "" : ` ${operator}`}
          </span>
          <span className="home-reveal block" style={homeRevealStyle(stage >= 2)}>
            What can I help you with?
          </span>
        </h1>

        <div className="home-reveal relative mt-7" style={homeRevealStyle(stage >= 3)}>
          <PromptBar
            autoFocus
            placeholder={chosen === undefined ? "The App has no agent to talk to" : `Ask ${assistantName(chosen)} anything…`}
            disabled={chosen === undefined}
            picker={{
              label: "assistant",
              options: assistantOptions(agents, (name) => (name === fallback && agents.length > 1 ? "default" : undefined)),
              value: chosen,
              onChange: setAgent,
            }}
            images={imageLimits(app)}
            webSearch={webSearch}
            commands={commands ?? []}
            commandsNote="Commands run in a conversation: start one, then run them there"
            onCommand={(name) => {
              setError(new Error(`/${name} runs in a conversation: start one with a first message, then run it there.`));
              throw new Error("no conversation");
            }}
            onSend={start}
          />
          {error !== undefined && (
            <div className="mt-3">
              <ErrorNote error={error} title="Not started" />
            </div>
          )}
        </div>

        <div className="home-reveal mt-6 flex flex-col" style={homeRevealStyle(stage >= 4)}>
          {recent.map((conversation) => {
            const title = chats.titleOf(conversation);
            return (
              <Link
                key={conversation.conversationId}
                to={pagePath("/conversations", conversation.conversationId)}
                className="-mx-2 flex items-center gap-3 rounded-control px-2 py-2.5 text-left text-[14px] text-ink transition-colors duration-150 hover:bg-hover"
              >
                <span className="flex w-[15px] shrink-0 justify-center text-ink-3">
                  <ChatBubble width={15} height={15} strokeWidth={1.9} />
                </span>
                <span className="min-w-0 truncate">Continue {title === NEW_CHAT ? `the chat with ${conversation.agent === undefined ? "the assistant" : assistantName(conversation.agent)}` : title}</span>
              </Link>
            );
          })}
          <div className="mt-1 flex flex-wrap items-center gap-x-5 gap-y-1 pl-0.5 text-[13px] text-ink-3">
            <span className="flex items-center gap-2 py-1">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
                <circle cx="5" cy="12" r="1.7" />
                <circle cx="12" cy="12" r="1.7" />
                <circle cx="19" cy="12" r="1.7" />
              </svg>
              Only you see this conversation and its answers
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

import { ChatBubble } from "iconoir-react";
import { defineView } from "@/lib/views";
import { ConversationPage } from "./conversation";
import { HomePage } from "./home";

/**
 * The chat: the home (`/conversations`: a new conversation of the dashboard's own) and every
 * conversation (`/conversations/:id`). The shell lists them in its sidebar and tabs, not as a view.
 */
export default defineView({
  id: "conversations",
  title: "Chats",
  icon: ChatBubble,
  requires: ["agent.observe"],
  order: 10,
  pages: [
    { path: "/conversations", component: HomePage, fill: true },
    { path: "/conversations/:id", component: ConversationPage, fill: true },
  ],
});

/**
 * A conversation live, from its server-sent events (`GET /admin/api/conversations/:id/events`): whether
 * a run is going, the answer being written, the tools running. The stream starts with a `snapshot`
 * and a client that fell behind gets a new one, so the state is rebuilt from each snapshot, never from
 * a count of events. What is written for good (entries) is read from the transcript again: `changes`
 * counts the times it changed.
 *
 * The stream is open only while the dashboard is active (`useActive`: the tab visible, the operator
 * there in the last minutes); it reconnects when it ends (on Cloudflare after a bounded number of
 * polled snapshots) and when the operator comes back.
 */

import { useEffect, useReducer } from "react";
import { useActive } from "@/lib/activity";
import { type ApiEvent, follow } from "@/lib/api";
import type { AssistantMessage as Assistant, Message, RunningTool } from "@/components/pikit/message";

export type { RunningTool };

export interface LiveState {
  connected: boolean;
  busy: boolean;
  /** The answer being written. */
  partial?: Assistant;
  tools: RunningTool[];
  /** Bumped whenever the transcript or the cost changed: read them again. */
  changes: number;
}

const INITIAL: LiveState = { connected: false, busy: false, tools: [], changes: 0 };

type Action = { type: "connected" } | { type: "disconnected" } | { type: "event"; event: ApiEvent };

type Change =
  | { type: "text_start" | "thinking_start" | "toolcall_start" | "block"; contentIndex: number; block: Assistant["content"][number] }
  | { type: "text_delta" | "thinking_delta"; contentIndex: number; delta: string }
  | { type: "toolcall_delta" }
  | { type: "message"; message: Assistant };

function applyChanges(partial: Assistant | undefined, changes: Change[]): Assistant | undefined {
  let message = partial;
  for (const change of changes) {
    if (change.type === "message") {
      message = change.message;
      continue;
    }
    if (message === undefined || change.type === "toolcall_delta") continue;
    const content = [...message.content];
    if ("delta" in change) {
      const part = content[change.contentIndex];
      if (part?.type === "text" && change.type === "text_delta") content[change.contentIndex] = { ...part, text: part.text + change.delta };
      if (part?.type === "thinking" && change.type === "thinking_delta") content[change.contentIndex] = { ...part, thinking: part.thinking + change.delta };
    } else {
      content[change.contentIndex] = change.block;
    }
    message = { ...message, content };
  }
  return message;
}

type ToolOutput = { trimStart?: number; append?: string } | { set: string };

function reduce(state: LiveState, action: Action): LiveState {
  if (action.type === "connected") return { ...state, connected: true };
  if (action.type === "disconnected") return { ...state, connected: false };
  const event = action.event;
  const changed = { ...state, changes: state.changes + 1 };
  switch (event.type) {
    case "snapshot": {
      const generation = event.generation as { message?: Assistant } | undefined;
      const tools = (event.tools as { callId: string; name: string; status: string; output?: string }[] | undefined) ?? [];
      return {
        ...changed,
        busy: event.run !== undefined,
        partial: generation?.message,
        tools: tools.filter((tool) => tool.status !== "done").map((tool) => ({ callId: tool.callId, name: tool.name, output: tool.output ?? "" })),
      };
    }
    case "run_start":
      return { ...state, busy: true };
    case "run_end":
      return { ...changed, busy: false, partial: undefined, tools: [] };
    case "message_start": {
      const message = event.message as Message;
      return message.role === "assistant" ? { ...state, partial: message } : state;
    }
    case "message_update":
      return { ...state, partial: applyChanges(state.partial, event.changes as Change[]) };
    case "message_end":
      return { ...changed, partial: undefined };
    case "tool_execution_start":
      return { ...state, tools: [...state.tools, { callId: String(event.toolCallId), name: String(event.toolName), output: "" }] };
    case "tool_execution_update": {
      const output = event.output as ToolOutput | undefined;
      if (output === undefined) return state;
      return {
        ...state,
        tools: state.tools.map((tool) => {
          if (tool.callId !== event.toolCallId) return tool;
          if ("set" in output) return { ...tool, output: output.set };
          return { ...tool, output: tool.output.slice(output.trimStart ?? 0) + (output.append ?? "") };
        }),
      };
    }
    case "tool_execution_end":
      return { ...changed, tools: state.tools.filter((tool) => tool.callId !== event.toolCallId) };
    case "entry_appended":
    case "usage_changed":
      return changed;
    default:
      return state;
  }
}

/** Follows conversation `id` live while mounted and active, reconnecting after a dropped stream. */
export function useLive(id: string): LiveState & { paused: boolean } {
  const [state, dispatch] = useReducer(reduce, INITIAL);
  const active = useActive();

  useEffect(() => {
    if (!active) return;
    const stop = new AbortController();
    void (async () => {
      while (!stop.signal.aborted) {
        try {
          const started = follow(`/conversations/${encodeURIComponent(id)}/events`, (event) => dispatch({ type: "event", event }), stop.signal);
          dispatch({ type: "connected" });
          await started;
        } catch {
          // Reconnect below.
        }
        // A stream stopped by this cleanup says nothing: the next one (another id, or a return) owns the state.
        if (stop.signal.aborted) return;
        dispatch({ type: "disconnected" });
        await new Promise((resolve) => setTimeout(resolve, 2000));
      }
    })();
    return () => stop.abort();
  }, [id, active]);

  return { ...state, paused: !active };
}

/**
 * What the Context panel shows of a transcript (`context.tsx`), read from pi-ai's JSON as it comes
 * (`unknown`): the images sent in it (`imagesOf`), and its sources (`sourcesOf`): what the web search
 * tool (`websearch`) and the fetch tool (`fetch`) returned, a card each (`ContextCards`' chunks). The
 * tools' text is read as they write it today (tool-websearch-brave, tool-fetch), defensively: what
 * does not parse is left out, never shown wrong. No imports: the kit's tests run it as it is.
 */

export interface SentImage {
  key: string;
  mimeType: string;
  data: string;
  /** Epoch ms of its message. */
  at?: number;
}

/** A source, as `ContextCards` shows it (its `ContextChunk`). */
export interface Source {
  key: string;
  title: string;
  meta?: string;
  body: string;
  source: string;
  href?: string;
  badge: string;
  tone: string;
}

type Fields = Record<string, unknown>;
const fields = (value: unknown): Fields => (typeof value === "object" && value !== null ? (value as Fields) : {});
const parts = (content: unknown): Fields[] => (Array.isArray(content) ? content.map(fields) : []);

/** The images of the person's messages, oldest first. */
export function imagesOf(messages: readonly unknown[]): SentImage[] {
  return messages.flatMap((each, i) => {
    const message = fields(each);
    if (message.role !== "user") return [];
    const at = typeof message.timestamp === "number" ? { at: message.timestamp } : {};
    return parts(message.content).flatMap((part, j) =>
      part.type === "image" && typeof part.data === "string" && typeof part.mimeType === "string" ? [{ key: `${i}:${j}`, mimeType: part.mimeType, data: part.data, ...at }] : [],
    );
  });
}

const hostOf = (url: string): string => {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
};
const isWeb = (url: unknown): url is string => typeof url === "string" && /^https?:\/\/\S+$/i.test(url);
const textOf = (content: unknown): string => parts(content).flatMap((part) => (part.type === "text" && typeof part.text === "string" ? [part.text] : [])).join("\n");

/**
 * `websearch`'s results: blocks apart by a blank line, each `N. Title (age)`, then its address, then
 * its snippet, indented.
 */
function searchResults(text: string, key: string): Source[] {
  return text.split(/\n\s*\n/).flatMap((block, i) => {
    const match = /^\s*\d+\.\s+(.+)\n\s+(\S+)(?:\n\s+([\s\S]+))?$/.exec(block.trimEnd());
    const url = match?.[2];
    if (match === null || !isWeb(url)) return [];
    const host = hostOf(url);
    return [{ key: `${key}:${i}`, title: match[1]?.trim() || host, meta: `result ${i + 1}`, body: match[3]?.replace(/\s+/g, " ").trim() ?? "", source: host, href: url, badge: "WEB", tone: "bg-accent-blue" }];
  });
}

/**
 * `fetch`'s answer: `HTTP <status> <text> · <content type> · <final address>`, a blank line, then the
 * content (an HTML page as `# Title`, its text, then `Links:`).
 */
function fetched(text: string, key: string, asked: unknown): Source[] {
  const [head = "", ...rest] = text.split("\n");
  const columns = /^HTTP (\d{3})\b/.test(head) ? head.split(" · ") : [];
  const status = /^HTTP (\d{3})/.exec(columns[0] ?? "")?.[1];
  const url = [columns[2]?.trim(), asked].find(isWeb);
  if (status === undefined || url === undefined) return [];
  const type = (columns[1] ?? "").split(";")[0]?.trim().toLowerCase() ?? "";
  let content = rest.join("\n").trim();
  let title: string | undefined;
  if (content.startsWith("# ")) {
    const end = content.indexOf("\n");
    title = (end === -1 ? content.slice(2) : content.slice(2, end)).trim();
    content = end === -1 ? "" : content.slice(end + 1).trim();
  }
  content = content.split(/\n\s*\nLinks:\n/)[0] ?? "";
  const host = hostOf(url);
  const badge = type.includes("html") ? "HTML" : type.includes("json") ? "JSON" : "TXT";
  return [
    {
      key,
      title: title || host,
      meta: status === "200" ? `${content.length.toLocaleString()} characters` : `HTTP ${status}`,
      body: content.replace(/\s+/g, " ").slice(0, 400),
      source: host,
      href: url,
      badge,
      tone: badge === "HTML" ? "bg-green" : badge === "JSON" ? "bg-orange" : "bg-accent-blue",
    },
  ];
}

/** The sources of `messages`: what each web search and fetch returned, oldest first. Failed calls are left out. */
export function sourcesOf(messages: readonly unknown[]): Source[] {
  const args = new Map<unknown, Fields>();
  for (const each of messages) {
    const message = fields(each);
    if (message.role !== "assistant") continue;
    for (const part of parts(message.content)) if (part.type === "toolCall") args.set(part.id, fields(part.arguments));
  }
  return messages.flatMap((each, i) => {
    const message = fields(each);
    if (message.role !== "toolResult" || message.isError === true) return [];
    const text = textOf(message.content);
    if (message.toolName === "websearch") return searchResults(text, `s${i}`);
    if (message.toolName === "fetch") return fetched(text, `f${i}`, args.get(message.toolCallId)?.url);
    return [];
  });
}
